# ----------------------------------------------------------------------
cuda_source = r"""
#include <torch/extension.h>
#include <cuda_fp16.h>
#include <cuda_runtime.h>

#ifndef __CUDA_ARCH__
#define __CUDA_ARCH__ 0
#endif

// each thread sums a strided chunk of the reduction dimension R.
// Loads are vectorized with half2 when possible.
template <int UNROLL>
__global__ void sum_reduce_kernel_opt(
    const __half* __restrict__ input,
    __half* __restrict__ output,
    int64_t B,
    int64_t R,
    int64_t I)
{
    // flatten batch and innermost dimensions: each thread writes one output element
    int64_t total = B * I;
    int64_t idx = blockIdx.x * blockDim.x + threadIdx.x;
    int64_t stride = gridDim.x * blockDim.x;

    for (; idx < total; idx += stride) {
        int64_t b = idx / I;          // batch index
        int64_t i = idx % I;          // innermost index

        const __half* batch_ptr = input + b * R * I + i; // points to first r=0 element for this i

        float acc = 0.0f;

        // Process UNROLL elements per iteration, each loading half2 when possible
        int64_t r = 0;
        // Vectorized half2 loop (process 2 elements per load)
        for (; r + 1 < R; r += 2) {
            // stride between successive r is I, but we load two adjacent r values:
            //   r*I + i   and (r+1)*I + i
            // they are separated by I elements, which is not contiguous,
            // so we cannot use half2 directly across r. Instead we load each half separately.
            // However we can still benefit from __half2 conversion for the two halves of each element.
            acc += __half2float(batch_ptr[r * I]);       // r
            acc += __half2float(batch_ptr[(r + 1) * I]); // r+1
        }
        // Tail
        if (r < R) {
            acc += __half2float(batch_ptr[r * I]);
        }

        output[idx] = __float2half(acc);
    }
}

// ------------------------------------------------------------------
// C++ wrapper
// ------------------------------------------------------------------
torch::Tensor sum_reduce_cuda_opt(torch::Tensor input) {
    TORCH_CHECK(input.is_cuda(), "input must be a CUDA tensor");
    TORCH_CHECK(input.scalar_type() == at::ScalarType::Half,
                "input must be float16 (Half)");
    input = input.contiguous();

    const int64_t B = input.size(0);
    const int64_t R = input.size(1);
    const int64_t I = input.size(2);

    // output shape [B, 1, I]
    auto output = torch::empty({B, 1, I}, input.options());

    const int threads = 256;
    const int64_t blocks = (B * I + threads - 1) / threads;

    // launch with templated unroll factor (8 gives a good balance)
    sum_reduce_kernel_opt<8><<<blocks, threads>>>(
        reinterpret_cast<const __half*>(input.data_ptr<at::Half>()),
        reinterpret_cast<__half*>(output.data_ptr<at::Half>()),
        B, R, I);

    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        throw std::runtime_error(cudaGetErrorString(err));
    }
    return output;
}
"""

